import re
for m in re.finditer(r'(?P<x>.)','é😀z'):
 print(m.group(),m.span(),m.span('x'),m.lastindex,m.lastgroup)

import re
for m in re.finditer(r'.*?','é😀\n'):
 print(repr(m.group()),m.span())

import re
try:re.sub('(a)',r'\2','z')
except re.error as e:print(type(e).__name__)

import re
m=re.match(r'(a)(?P<opt>b)?','a')
for t in ['\\',r'\g',r'\gx',r'\g<>',r'\g<',r'\g<1',r'\g<-1>',r'\g<a-b>',r'\g<١>',r'\g<missing>',r'\g<3>',r'\g<000003>',r'\g<999999999999999999999>',r'\11',r'\118',r'\400',r'\777',r'\x',r'\q','é😀'+r'\x']:
 try:print(repr(m.expand(t)))
 except (re.error,IndexError) as e:print(type(e).__name__,str(e))

import re
m=re.match('(a)','a')
for t in [r'\g<a\>b>',r'\g<a\>', '\\g<a\\',r'\g<\>:',r'\g<a\x>',r'\g<1\\>',r'\g<a\>>',r'\g<missing>'+'\\',r'\g<>'+'\\',r'\q'+'\\',r'\11'+'\\',r'\400'+'\\',r'\1x'+'\\']:
 try:print(repr(m.expand(t)))
 except (re.error,IndexError) as e:print(type(e).__name__,str(e))

import re
p=re.compile('a')
print(p.match('ab',endpos=1).span(),p.search('ab',endpos=1).span(),p.fullmatch('ab',endpos=1).span())
print(p.findall('ab',endpos=1),[m.span() for m in p.finditer('ab',endpos=1)])
def invalid(pos):
 for f in [lambda:p.match('a',pos),lambda:p.search('a',pos),lambda:p.fullmatch('a',pos),lambda:p.findall('a',pos),lambda:p.finditer('a',pos)]:
  try:f()
  except TypeError:print('TypeError')
invalid(None)

import re
p=re.compile('a')
print(p.match('a',2**40),p.search('a',-2**40).span(),p.fullmatch('a',0,2**40).span())
print(p.findall('a',endpos=2**40),[m.span() for m in p.finditer('a',endpos=2**40)])
for f in [lambda:p.match('a',2**80),lambda:p.search('a',endpos=-2**80)]:
 try:f()
 except OverflowError:print('OverflowError')
